/**
 * ISO-5667-6 regulation-table seed builders (Plan 3 Task 23, 2026-09-18).
 *
 * SR-1: every seeded value and every `verbatim_quote` was read in this session
 * from the SPANISH transcript `Desktop\Ciruclar economy, sustanability and water
 * test\ISO 5667-6\ISO-5667-6-2015.txt` (2511 lines; NCh-ISO 5667/6:2015 — the
 * Chilean adoption of ISO 5667-6:2014, INN licence copy, pdftotext). The spans
 * live in `regulation-tables-quotes-iso5667_6.ts` (generated by line range, never
 * retyped); the line range is in each span's name. A Spanish plain-text
 * transcript is a VC-grade source by ruling (no PDF exists for this standard —
 * docs/verification-doctrine.md names ISO-5667-6 as the one source-absent
 * standard) — EVERY table here ships `verification_status: 'imported_unverified'`;
 * nothing is upgraded. Verified by
 * `scripts/regulation-tables/verify-regulation-tables.ts iso5667_6 "<transcript>"`.
 * Emitted as `20260917102300_regulation_tables_seed_iso5667_6.sql` (no earlier
 * ISO-5667-6 table seed exists — nothing superseded).
 *
 * Edition: the title page prints "Primera edición" / "2015.02.24" (L4–L5) and the
 * reference number "NCh-ISO 5667/6:2015" (L28–L29); prod `standards.version` is
 * "2014 (ISO 5667-6:2014; NCh-ISO 5667/6:2015 declared identical)" (read-only
 * 2026-09-18) → token `'2015'` (the printed edition of the transcript).
 *
 * The standard prints NO numeric table (Tabla 1 is a prose advantages /
 * disadvantages matrix, Tablas B.1 / B.2 a form template, Tabla D.1 editorial
 * changes): every "table" below is either a printed SENTENCE rule (threshold per
 * clause) read by `lookup()` from the row exprs / equations — so no figure is
 * typed into a formula — or a printed text catalogue (§13.1 a) – q)). Key tokens
 * (G-A3): ANNEXA.roughness (muy_irregular / liso) are the tokens of the select
 * `bed_roughness_hint` CREATED by `field-configs/iso5667_6.ts`; S13_1.item
 * (a … q) are the tokens of the created `report_items_6` select_many; the four
 * sentence tables are single-row and keyed by a literal read inside the
 * equations (`lookup('S7_1', 'general', …)`).
 *
 * Unreadable / ambiguous cells (all recorded, nothing corrected):
 *   - iso5667_6-U-1: the Ecuación (A.1) block (L2152–L2155) prints "0,13b 2c 0,7c
 *     + 2 g" over "gd" with a stray space between "2" and "g" and a lost radical —
 *     √g vs 2g is NOT decidable from the txt; no table cell depends on it (the
 *     prod equation A.1 is not rewritten; the EJEMPLO row carries the printed
 *     83 m / 683 m as text only).
 */
import type { RegulationTable, RegulationRow } from './regulation-tables';
import { Q } from './regulation-tables-quotes-iso5667_6';

const STD = 'ISO-5667-6';
export const ISO5667_6_EDITION = '2015';
const ED = ISO5667_6_EDITION;
const STATUS = 'imported_unverified' as const; // VC source (Spanish txt) — every table

const collapse = (s: string) => s.replace(/\s+/g, ' ').trim();
/** Build-time SR-1 guard: every seeded cell text must be printed inside the named span (whitespace-collapsed). */
function inSpan(quote: string, cell: string | null, where: string): void {
  if (cell !== null && !collapse(quote).includes(collapse(cell))) throw new Error(`${where}: cell "${cell}" is not inside its verbatim span`);
}

// ---------------------------------------------------------------------------
// ANNEXA — Anexo A (informativo), the Chézy coefficient: legend L2165 "c = coeficiente de Chézy para el
// tramo (15 < c < 50)" and the EJEMPLO L2179–L2183 with the two extreme values — 15 (fondo muy irregular)
// and 50 (fondo muy liso). Keys = the two printed bed descriptions (tokens of the created select
// `bed_roughness_hint`); `c_example` fills the created `c_hint` (lookup_fill, role value) as an
// ANHALTSWERT beside the engineer's typed `c` (SR-2: the printed RANGE 15 < c < 50 is never auto-picked;
// `c_min` / `c_max` are its bounds, asserted against L2165). Policy: "(informativo)" (L2140) + "se puede
// calcular aproximadamente" (L2147) ⇒ anhaltswert. The printed example results (83 m / 683 m) are kept as
// text only — the formula reading (√g vs 2g) is iso5667_6-U-1.
// ---------------------------------------------------------------------------
export const ANNEXA_ROWS = [
  { roughness: 'muy_irregular', label: 'fondo muy irregular (sehr unregelmäßige Sohle): c = 15', c_example: 15, descripcion: 'fondo muy irregular, es decir, el curso de agua es muy rápido y turbulento', l_example_m: '83 m', printed: ['uno de 15 (fondo muy irregular', 'después de 83 m'] },
  { roughness: 'liso', label: 'fondo muy liso (sehr glatte Sohle): c = 50', c_example: 50, descripcion: 'fondo muy liso, es decir, un curso de agua muy tranquilo, de movimiento lento', l_example_m: '683 m', printed: ['otro de 50 (fondo muy liso', 'recorrido 683 m'] },
] as const;
export function annexAAsTable(): RegulationTable {
  inSpan(Q.L2165, '15 < c < 50', 'ANNEXA range');
  const rows: RegulationRow[] = ANNEXA_ROWS.map((r, i) => {
    for (const p of r.printed) inSpan(Q.L2179_2183, p, `ANNEXA ${r.roughness}`);
    inSpan(Q.L2179_2183, r.descripcion, `ANNEXA ${r.roughness} descripcion`);
    return { row_key: r.roughness, keys: { roughness: r.roughness }, group_label: null, label_de: r.label, order_index: i,
      values: { c_example: r.c_example, c_min: 15, c_max: 50, descripcion: r.descripcion, l_example_m: r.l_example_m }, verbatim_quote: Q.L2179_2183 };
  });
  return { standard_code: STD, edition: ED, table_code: 'ANNEXA', title_de: 'Chézy-Koeffizient c nach Sohlenbeschaffenheit (Anexo A EJEMPLO: 15 fondo muy irregular / 50 fondo muy liso; Bereich 15 < c < 50)', clause_reference: 'Anexo A (informativo), Ecuación (A.1), EJEMPLO', page_ref: null,
    key_columns: ['roughness'],
    value_columns: [{ name: 'c_example', type: 'number' }, { name: 'c_min', type: 'number' }, { name: 'c_max', type: 'number' }, { name: 'descripcion', type: 'string' }, { name: 'l_example_m', type: 'string' }],
    override_policy: 'anhaltswert',
    override_quote: `${Q.L2139_2140} — ${Q.L2146_2148}`,
    verification_status: STATUS, rows };
}

// ---------------------------------------------------------------------------
// S13_1 — §13.1 (L1946–L2006): the seventeen report items a) – q) "que se podrían considerar para su
// inclusión" (L1947–L1948 ⇒ anhaltswert). One row per printed item; `letter` is the printed marker,
// `text` the printed item without it (asserted inside the row span, whitespace-collapsed; item i) wraps
// over a page break — the furniture line L1984 is part of its span). Keys = the tokens of the created
// `report_items_6` select_many (-11); the prod single-value enum `report_item` (17 tokens) stays until
// iso5667_6-D-1 is ratified.
// ---------------------------------------------------------------------------
export const S13_1_ROWS = [
  { item: 'a', quote: Q.L1950 }, { item: 'b', quote: Q.L1952_1953 }, { item: 'c', quote: Q.L1964_1965 }, { item: 'd', quote: Q.L1967 },
  { item: 'e', quote: Q.L1969 }, { item: 'f', quote: Q.L1971_1972 }, { item: 'g', quote: Q.L1974 }, { item: 'h', quote: Q.L1976_1977 },
  { item: 'i', quote: Q.L1979_1985 }, { item: 'j', quote: Q.L1987 }, { item: 'k', quote: Q.L1989 }, { item: 'l', quote: Q.L1991 },
  { item: 'm', quote: Q.L1993 }, { item: 'n', quote: Q.L1995 }, { item: 'o', quote: Q.L2001 }, { item: 'p', quote: Q.L2003_2004 }, { item: 'q', quote: Q.L2006 },
] as const;
/**
 * The printed item text without its "x)" marker and without the page furniture (whitespace-collapsed).
 * Returns the printed FRAGMENTS (one per contiguous run of text lines — item i) is two fragments around
 * the furniture line L1984); each fragment is asserted inside the span by the caller, the cell is their join.
 */
export function s131ItemFragments(item: string, quote: string): string[] {
  const frags: string[] = [];
  let cur: string[] = [];
  for (const l of quote.split('\n')) {
    if (l.startsWith('USO EXCLUSIVO')) { if (cur.length) frags.push(collapse(cur.join(' '))); cur = []; }
    else cur.push(l);
  }
  if (cur.length) frags.push(collapse(cur.join(' ')));
  const m = frags[0].match(/^([a-q])\)\s+(.*)$/);
  if (!m || m[1] !== item) throw new Error(`S13_1 ${item}: span does not start with "${item})"`);
  frags[0] = m[2];
  return frags;
}
export function s131AsTable(): RegulationTable {
  const rows: RegulationRow[] = S13_1_ROWS.map((r, i) => {
    const frags = s131ItemFragments(r.item, r.quote);
    for (const f of frags) inSpan(r.quote, f, `S13_1 ${r.item}`);
    const text = frags.join(' ');
    return { row_key: r.item, keys: { item: r.item }, group_label: null, label_de: `${r.item}) ${text}`, order_index: i,
      values: { letter: `${r.item})`, text }, verbatim_quote: r.quote };
  });
  return { standard_code: STD, edition: ED, table_code: 'S13_1', title_de: 'Elemente des Probenahmeberichts a) – q) (§13.1 „asuntos que se podrían considerar para su inclusión“)', clause_reference: '§13.1', page_ref: null,
    key_columns: ['item'],
    value_columns: [{ name: 'letter', type: 'string' }, { name: 'text', type: 'string' }],
    override_policy: 'anhaltswert',
    override_quote: Q.L1946_1948,
    verification_status: STATUS, rows };
}

// ---------------------------------------------------------------------------
// S7_1 — §7.1 (L1165–L1169): "las muestras obtenidas de posiciones al menos 30 cm por encima del fondo de un
// curso de agua y a una distancia similar debajo de la superficie, suelen ser satisfactorias". One row keyed
// by the literal `general`; read in row scope by the `sampling_points_6.depth_ok` badge (ISO-5667-6-02).
// "Siempre que sea posible … suelen ser satisfactorias" ⇒ anhaltswert. The §7.3 / §7.4 / §7.5 wording
// ("alrededor de 30 cm por debajo de la superficie, o … a media altura", L1284–L1285 / L1311–L1312 /
// L1328–L1330) and §8.1 ("dentro de 30 cm de la superficie", L1370–L1371) are recorded in iso5667_6-J-1 —
// the ≥ 30 / ≥ 30 reading follows the brief and prod CR-016 / VR.
// ---------------------------------------------------------------------------
export function s71AsTable(): RegulationTable {
  for (const p of ['al menos 30 cm por encima del fondo', 'a una distancia', 'similar debajo de la superficie', 'suelen ser satisfactorias']) inSpan(Q.L1165_1169, p, 'S7_1 general');
  const rows: RegulationRow[] = [{ row_key: 'general', keys: { regla: 'general' }, group_label: null, label_de: 'Position im Gewässer: ≥ 30 cm über der Sohle und eine ähnliche Distanz unter der Oberfläche (§7.1)', order_index: 0,
    values: { height_above_bed_min_cm: 30, depth_below_surface_min_cm: 30, gedruckt: 'al menos 30 cm por encima del fondo de un curso de agua y a una distancia similar debajo de la superficie', modal: 'suelen ser satisfactorias' }, verbatim_quote: Q.L1165_1169 }];
  return { standard_code: STD, edition: ED, table_code: 'S7_1', title_de: 'Probenahmeposition nach §7.1: mindestens 30 cm über der Sohle und eine ähnliche Distanz unter der Oberfläche', clause_reference: '§7.1', page_ref: null,
    key_columns: ['regla'],
    value_columns: [{ name: 'height_above_bed_min_cm', type: 'number', unit: 'cm' }, { name: 'depth_below_surface_min_cm', type: 'number', unit: 'cm' }, { name: 'gedruckt', type: 'string' }, { name: 'modal', type: 'string' }],
    override_policy: 'anhaltswert',
    override_quote: `${Q.L1165_1169} — ${Q.L1284_1285}`,
    verification_status: STATUS, rows };
}

// ---------------------------------------------------------------------------
// S5_1_3 — §5.1.3 (L859–L863): travel-time measurements "en un mínimo de cinco caudales diferentes"; extrapolation
// "fuera del 10% de un valor de medición del caudal puede proporcionar información incorrecta". One row keyed
// `travel_time`; read by ISO-5667-6-04-D2 / D3. "se deberían realizar" ⇒ anhaltswert (prod CR-009 warns).
// The word "cinco" is asserted; 5 is its arithmetic reading.
// ---------------------------------------------------------------------------
export function s513AsTable(): RegulationTable {
  for (const p of ['un mínimo de cinco caudales diferentes', 'fuera del 10%', 'se deberían realizar']) inSpan(Q.L859_863, p, 'S5_1_3 travel_time');
  const rows: RegulationRow[] = [{ row_key: 'travel_time', keys: { regla: 'travel_time' }, group_label: null, label_de: 'Fließzeit: Messungen bei mindestens fünf verschiedenen Durchflüssen; Extrapolation außerhalb von 10 % unsicher (§5.1.3)', order_index: 0,
    values: { flows_min: 5, flows_min_gedruckt: 'cinco', extrapolation_max_pct: 10, modal: 'se deberían realizar' }, verbatim_quote: Q.L859_863 }];
  return { standard_code: STD, edition: ED, table_code: 'S5_1_3', title_de: 'Fließzeitmessung nach §5.1.3: mindestens fünf Durchflüsse, Extrapolation höchstens 10 %', clause_reference: '§5.1.3', page_ref: null,
    key_columns: ['regla'],
    value_columns: [{ name: 'flows_min', type: 'number' }, { name: 'flows_min_gedruckt', type: 'string' }, { name: 'extrapolation_max_pct', type: 'number', unit: '%' }, { name: 'modal', type: 'string' }],
    override_policy: 'anhaltswert',
    override_quote: `${Q.L846_849} — ${Q.L859_863}`,
    verification_status: STATUS, rows };
}

// ---------------------------------------------------------------------------
// S5_1_4 — §5.1.4 (L897–L905): the part of the cross-section carrying "alrededor del 90%" of the flow;
// "aproximadamente seis muestras repartidas a través de la parte"; "al menos tres caudales" (minimum, modal,
// maximum). One row keyed `heterogeneity`; read by ISO-5667-6-03-D2 (the count verdict — "aproximadamente
// seis" is encoded as ≥ 6 like prod CR-008, iso5667_6-J-2); the distinct-flow count is not expressible
// (iso5667_6-F-1). "se deberían tomar" / "De preferencia" ⇒ anhaltswert.
// ---------------------------------------------------------------------------
export function s514AsTable(): RegulationTable {
  for (const p of ['alrededor del 90%', 'aproximadamente seis muestras', 'al menos tres caudales', 'se deberían tomar']) inSpan(Q.L897_905, p, 'S5_1_4 heterogeneity');
  const rows: RegulationRow[] = [{ row_key: 'heterogeneity', keys: { regla: 'heterogeneity' }, group_label: null, label_de: 'Heterogenitätstest: ≈ 6 Proben über den Querschnittsteil mit ≈ 90 % des Durchflusses, bei ≥ 3 Durchflüssen (§5.1.4)', order_index: 0,
    values: { flow_share_pct: 90, samples_approx: 6, samples_gedruckt: 'aproximadamente seis', flows_min: 3, flows_min_gedruckt: 'al menos tres', modal: 'se deberían tomar' }, verbatim_quote: Q.L897_905 }];
  return { standard_code: STD, edition: ED, table_code: 'S5_1_4', title_de: 'Heterogenitätstest nach §5.1.4: etwa sechs Proben im 90-%-Durchflussteil, mindestens drei Durchflüsse', clause_reference: '§5.1.4', page_ref: null,
    key_columns: ['regla'],
    value_columns: [{ name: 'flow_share_pct', type: 'number', unit: '%' }, { name: 'samples_approx', type: 'number' }, { name: 'samples_gedruckt', type: 'string' }, { name: 'flows_min', type: 'number' }, { name: 'flows_min_gedruckt', type: 'string' }, { name: 'modal', type: 'string' }],
    override_policy: 'anhaltswert',
    override_quote: `${Q.L889_891} — ${Q.L897_899}`,
    verification_status: STATUS, rows };
}

// ---------------------------------------------------------------------------
// S10_8 — §10.8 (L1765–L1768): "el tiempo para todos los incrementos que se adopten debería ser menor que
// 5 min" (when no change in composition is known). One row keyed `incremental`; read by ISO-5667-6-09-D2
// (strict "<", like prod CR-021). "debería ser menor" ⇒ anhaltswert.
// ---------------------------------------------------------------------------
export function s108AsTable(): RegulationTable {
  for (const p of ['debería ser menor', 'que 5 min']) inSpan(Q.L1765_1768, p, 'S10_8 incremental');
  const rows: RegulationRow[] = [{ row_key: 'incremental', keys: { regla: 'incremental' }, group_label: null, label_de: 'Inkrementelle Probenahme: Gesamtzeit aller Inkremente < 5 min, wenn keine Änderung der Zusammensetzung bekannt ist (§10.8)', order_index: 0,
    values: { total_time_max_min: 5, comparator: '<', modal: 'debería ser menor' }, verbatim_quote: Q.L1765_1768 }];
  return { standard_code: STD, edition: ED, table_code: 'S10_8', title_de: 'Gesamtzeit der Inkremente nach §10.8: weniger als 5 min', clause_reference: '§10.8', page_ref: null,
    key_columns: ['regla'],
    value_columns: [{ name: 'total_time_max_min', type: 'number', unit: 'min' }, { name: 'comparator', type: 'string' }, { name: 'modal', type: 'string' }],
    override_policy: 'anhaltswert',
    override_quote: Q.L1765_1768,
    verification_status: STATUS, rows };
}

/** The live ISO-5667-6 set (six tables): the two text tables of the brief (ANNEXA, S13_1) plus the four sentence rules the equations / badges read. */
export function iso56676SeedTables(): RegulationTable[] {
  return [annexAAsTable(), s131AsTable(), s71AsTable(), s513AsTable(), s514AsTable(), s108AsTable()];
}
